cat >> app/routes/app/discussions/__tests__/discussions.test.tsx <<'EOF'

test('should list pinned discussions first with a pinned badge', async () => {
  const fakeUser = await createUser();
  const regularDiscussion = await seedDiscussion({
    teamId: fakeUser.teamId,
    title: 'Regular discussion',
  });
  const pinnedDiscussion = await seedDiscussion({
    teamId: fakeUser.teamId,
    title: 'Pinned discussion',
    pinned: true,
  });

  await renderApp(<DiscussionsRoute />, { user: fakeUser });

  await screen.findByText(pinnedDiscussion.title);

  // the first row is the table header
  const [, firstRow, secondRow] = screen.getAllByRole('row');

  expect(within(firstRow).getByText(pinnedDiscussion.title)).toBeInTheDocument();
  expect(within(firstRow).getByText('Pinned')).toBeInTheDocument();

  expect(
    within(secondRow).getByText(regularDiscussion.title),
  ).toBeInTheDocument();
  expect(within(secondRow).queryByText('Pinned')).not.toBeInTheDocument();
});
EOF
